<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({ layout:'dashboard', middleware:'auth' }); useHead({title:'Projets'})
type Project={id:string;reference:string|null;title:string;status:string;startDate:string|null;endDate:string|null;plannedBudget:string|null;actualBudget:string|null;projectClients:{client:{id:string;name:string}}[];projectIntervenors:{assignmentStatus:string;intervenor:{id:string;firstName:string;lastName:string}}[];_count:{documents:number;reports:number;billingDocuments:number}}
const {data,error,refresh}=await useFetch<ApiSuccess<Project[]>>('/api/projects');const projects=computed(()=>data.value?.data??[]);const date=(v:string|null)=>v?new Date(v).toLocaleDateString('fr-FR'):'—'
</script>
<template><div><div class="page-head"><div><h1>Projets</h1><p>Suivi opérationnel des actions IFICS.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger les projets.</div><div v-else-if="!projects.length" class="empty-state">Aucun projet accessible.</div><div v-else class="grid grid-2"><article v-for="project in projects" :key="project.id" class="card card-pad"><div class="actions"><span class="badge">{{ project.status }}</span><span v-if="project.reference" class="badge badge-muted">{{ project.reference }}</span></div><h2>{{ project.title }}</h2><p class="muted">{{ date(project.startDate) }} → {{ date(project.endDate) }}</p><p><strong>Client :</strong> {{ project.projectClients[0]?.client.name || 'Non rattaché' }}</p><p><strong>Intervenants :</strong> {{ project.projectIntervenors.length }} · <strong>Documents :</strong> {{ project._count.documents }} · <strong>Bilans :</strong> {{ project._count.reports }}</p></article></div></div></template>
<style scoped>h2{margin:14px 0 6px}</style>
